function a(t){if(t<1024)return`${t} B`;const e=["KB","MB","GB","TB"];let n=t/1024,r=0;for(;n>=1024&&r<e.length-1;)n/=1024,r++;return`${n.toFixed(1)} ${e[r]}`}function f(t){if(!t)return"never";const e=new Date(t).getTime();return Number.isNaN(e)?t:u((Date.now()-e)/1e3)}function u(t){if(t==null||Number.isNaN(t))return"never";if(t<0)return"just now";const e=[["day",86400],["hour",3600],["minute",60]];for(const[n,r]of e)if(t>=r){const i=Math.floor(t/r);return`${i} ${n}${i===1?"":"s"} ago`}return"just now"}function s(t){if(!t)return"—";const e=new Date(t);return Number.isNaN(e.getTime())?t:e.toLocaleString()}function $(t){if(t<1e3)return`${t} ms`;const e=t/1e3;return e<60?`${e.toFixed(1)} s`:`${Math.floor(e/60)}m ${Math.round(e%60)}s`}function o(t){const e=["B","KiB","MiB","GiB","TiB"];let n=t,r=0;for(;n>=1024&&r<e.length-1;)n/=1024,r++;return r===0?`${t} B`:`${n.toFixed(1)} ${e[r]}`}function c(t){const e=`${Math.round(t.percent)}% — ${o(t.bytes_done)} of ${o(t.total_bytes)}`;if(!t.seconds_remaining)return e;const n=Math.max(1,Math.round(t.seconds_remaining/60)),r=n>=90?`${Math.round(n/60)} hours`:`${n} minute${n===1?"":"s"}`;return`${e} (about ${r} left)`}export{s as a,f as b,a as c,c as d,$ as e,u as f};
